import{c as a,Q as s,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"核函数配置","description":"","frontmatter":{},"headers":[{"level":1,"title":"核函数配置","slug":"核函数配置"},{"level":2,"title":"核函数定义","slug":"核函数定义"},{"level":2,"title":"\\\\_\\\\_launch\\\\_bounds\\\\_\\\\_\\\\(N\\\\)","slug":"__launch_bounds__n"},{"level":2,"title":"\\\\>\\\\>调用","slug":"调用"},{"level":2,"title":"asc\\\\_vf\\\\_call调用","slug":"asc_vf_call调用"}],"relativePath":"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/核函数配置-147.md","filePath":"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/核函数配置-147.md"}'),e={name:"api/SIMT-API/SIMD与SIMT混合编程简介/扩展语法/核函数配置-147.md"};function d(_,t,i,p,c,o){return s(),l("div",null,[...t[0]||(t[0]=[n(`<h1 id="核函数配置" tabindex="-1">核函数配置 <a class="header-anchor" href="#核函数配置" aria-label="Permalink to &quot;核函数配置&quot;">​</a></h1><h2 id="核函数定义" tabindex="-1">核函数定义 <a class="header-anchor" href="#核函数定义" aria-label="Permalink to &quot;核函数定义&quot;">​</a></h2><p>核函数是SIMD与SIMT混合编程的Device侧入口函数，负责协调整个算子的执行流程，包括VF的调度和调用。vector计算单元的混合编程场景下，函数定义语法为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ __vector__ void kernel_name(__gm__ type* param1, __gm__ type* param2, ...);</span></span></code></pre></div><p>关键修饰符说明如下：</p><ul><li>__global__：必需修饰符，作用为标识核函数，表明可在Host侧通过&lt;&lt;&lt;...&gt;&gt;&gt;调用。</li><li>__vector__：必需修饰符，作用为标识函数是在Device侧AIV核上执行。</li></ul><p>核函数定义有以下几个约束：</p><ul><li>返回值类型必须是void；</li><li>入参支持指针类型（需使用__gm__修饰）和Ascend C内置数据类型；</li><li>指针参数必须是指向Global Memory上的内存地址，使用__gm__修饰。</li></ul><h2 id="launch-bounds-n" tabindex="-1">__launch_bounds__(N) <a class="header-anchor" href="#launch-bounds-n" aria-label="Permalink to &quot;\\_\\_launch\\_bounds\\_\\_\\(N\\)&quot;">​</a></h2><p>在多线程并发执行时，每个线程使用较少的寄存器可以让更多的线程和线程块驻留在AI处理器上，从而提升性能。因此，编译器会采用启发式算法，将寄存器溢出（register spilling）和指令数量控制在最低水平，同时尽量减少寄存器的使用量。应用程序可以通过在__global__函数定义中使用__launch_bounds__()限定符来限制启动边界（launch bounds），提供附加信息辅助编译器优化这一过程，这属于可选配置。</p><p>__launch_bounds__(N)：函数标记宏，在SIMT VF入口函数上可选配置，用于在编译期指定SIMT VF启动的最大线程数。若未配置__launch_bounds__，最大线程数默认为1024。参数N需要满足：</p><ul><li><p>N &gt;= dimx * dimy * dimz；dimx，dimy，dimz为表示线程的dim3结构体。</p></li><li><p>N的取值范围为1到2048。</p><p>最大线程数决定了每个线程可分配的寄存器数量，具体对应关系请见下表，寄存器用于存储线程中的局部变量，若局部变量的个数超出寄存器个数，容易出现栈溢出等问题。建议最大线程数与启动VF任务的dim3线程数保持一致。</p><p><strong>表 1</strong> __launch_bounds__的Thread数量与每个Thread可用寄存器数</p></li></ul><table tabindex="0"><thead><tr><th>Thread的个数(个)</th><th>每个Thread可用寄存器个数(个)</th></tr></thead><tbody><tr><td>1025~2048</td><td>16</td></tr><tr><td>513~1024</td><td>32</td></tr><tr><td>257~512</td><td>64</td></tr><tr><td>1~256</td><td>127</td></tr></tbody></table><h2 id="调用" tabindex="-1">&lt;&lt;&lt;&gt;&gt;&gt;调用 <a class="header-anchor" href="#调用" aria-label="Permalink to &quot;&lt;&lt;&lt;\\&gt;\\&gt;\\&gt;调用&quot;">​</a></h2><p>核函数的调用是通过&lt;&lt;&lt;...&gt;&gt;&gt;内核调用符在Host侧调用，语法如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kernel_name&lt;&lt;&lt;block_num, dyn_ub_size, stream&gt;&gt;&gt;(args...);</span></span></code></pre></div><p>内核调用符内的配置参数说明如下：</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>约束</th></tr></thead><tbody><tr><td>block_num</td><td>uint32_t</td><td>设置核函数启用的核数</td><td>取值范围[1, 65535]</td></tr><tr><td>dyn_ub_size</td><td>uint32_t</td><td>指定动态内存大小，单位为字节</td><td>不超过最大可配置值：256KB - 8KB - 32KB - 静态内存</td></tr><tr><td>stream</td><td>aclrtStream</td><td>用于维护异步操作执行顺序</td><td>无</td></tr></tbody></table><h2 id="asc-vf-call调用" tabindex="-1">asc_vf_call调用 <a class="header-anchor" href="#asc-vf-call调用" aria-label="Permalink to &quot;asc\\_vf\\_call调用&quot;">​</a></h2><p>在SIMD与SIMT混合编程场景，需使用asc_vf_call启动SIMT VF（Vector Function）子任务，通过参数配置，启动指定数目的线程，执行指定的SIMT VF函数。其函数原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;auto funcPtr, typename... Args&gt;</span></span>
<span class="line"><span>__aicore__ inline void asc_vf_call(dim3 threadNums, Args &amp;&amp;...args)</span></span></code></pre></div><p>其中模板参数为指定的SIMT VF函数名以及SIMT VF函数参数，具体描述如下：</p><p><strong>表 2</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>funcPtr</td><td>用于指定SIMT入口核函数。</td></tr><tr><td>Args</td><td>定义可变参数，用于传递实参到SIMT入口核函数。</td></tr></tbody></table><p><strong>表 3</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>threadNums</td><td>输入</td><td>dim3结构，定义为{dimx，dimy，dimz}，用于指定SIMT线程块内线程数量。线程总数为dimx * dimy * dimz，该值的大小必须小于等于2048，建议为32的倍数。</td></tr><tr><td>args</td><td>输入</td><td>可变参数，用于传递实参到SIMT入口核函数。</td></tr></tbody></table><p>以下示例展示了SIMD与SIMT混合编程场景下如何使用asc_vf_call调用__simt_vf__函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;simt_api/common_functions.h&quot;</span></span>
<span class="line"><span>__simt_vf__ inline void add_simt(</span></span>
<span class="line"><span>    __gm__ float* dst, __gm__ float* src0, __gm__ float* src1) </span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // simt 代码</span></span>
<span class="line"><span>    int idx = threadIdx.x + blockIdx.x * blockDim.x;</span></span>
<span class="line"><span>    dst[idx] = src0[idx] + src1[idx];</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__global__ __vector__ void add_custom(__gm__ float* x, __gm__ float* y, __gm__ float* z)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // asc_vf_call启动SIMT VF子任务，函数名为：add_simt，配置blockDim为dim3{1024, 1, 1}</span></span>
<span class="line"><span>    asc_vf_call&lt;add_simt&gt;(dim3{1024, 1, 1}, z, x, y);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,28)])])}const u=a(e,[["render",d]]);export{h as __pageData,u as default};
